args:
["main: msg: [
  {
    pat: [ {aim: web}, {save: item} ]
    doc: "Save a todo item"
    params: { id: "string" }
    web: { allow: true }
    api: { active: true }
  }
]
"]

["main: msg: [
  { pat: [ {aim: todo}, {save: item} ] }
  { pat: [ {aim: web}, {on: todo}, {save: item} ], file: "./web_save_item" }
]
"]

["main: msg: aim: web: {
  get: info: {}
  on: todo: { save: item: { '$': { file: './web_save_item' } } }
}
"]
